const packageHash = "350652e7e16fefa40038d9d3d1b3fca9a63e1aa6b7d110677e327e84dda6093c";
const digest = content => createHash('sha256').update(content).digest('hex');
async function optionalFile(path) {
  try {
    const info = await lstat(path);
    if (!info.isFile() || info.isSymbolicLink()) throw new Error(`Not a regular source file: ${path}`);
    return await readFile(path);
  } catch (error) { if (error.code === 'ENOENT') return null; throw error; }
}

async function main() {
  const root = await realpath(process.cwd());
  const pkg = await optionalFile(join(root, 'package.json'));
  if (!pkg || digest(pkg) !== packageHash)
    throw new Error('Run this command from the original localisation project folder. Its package.json must be unchanged.');
  const changes = [];
  for (const [name, update] of Object.entries(updates)) {
    const target = resolve(root, name);
    const rel = relative(root, target);
    if (isAbsolute(rel) || rel.startsWith('..') || !rel) throw new Error('Invalid update path');
    let parent = dirname(target);
    while (parent !== root) {
      try {
        const real = await realpath(parent);
        if (real !== root && !real.startsWith(root + sep)) throw new Error(`Source folder escapes the project: ${name}`);
      } catch (error) { if (error.code !== 'ENOENT') throw error; }
      parent = dirname(parent);
    }
    const existing = await optionalFile(target);
    const currentHash = existing === null ? null : digest(existing);
    const after = digest(update.content);
    if (currentHash === after) continue;
    if (!update.before.includes(currentHash))
      throw new Error(`Your copy of ${name} differs from the released version. Nothing was changed. Ask for help rather than overwriting it.`);
    changes.push({ name, target, content: update.content, existing, after });
  }
  if (!changes.length) { console.log('The English test update is already installed.'); return; }
  // Validate all paths and hashes before changing anything, then back up every
  // replaced file before the first write. No browser or dependency data is touched.
  const backup = join(root, 'local', 'update-backups', new Date().toISOString().replaceAll(':', '-'));
  await mkdir(backup, { recursive: true, mode: 0o700 });
  for (const item of changes) {
    if (item.existing === null) continue;
    const path = join(backup, item.name);
    await mkdir(dirname(path), { recursive: true, mode: 0o700 });
    await copyFile(item.target, path);
    if (digest(await readFile(path)) !== digest(item.existing)) throw new Error('Backup verification failed; update stopped.');
  }
  for (const item of changes) {
    await mkdir(dirname(item.target), { recursive: true });
    await writeFile(item.target, item.content);
    if (digest(await readFile(item.target)) !== item.after) throw new Error(`Update verification failed for ${item.name}`);
  }
  console.log(`Installed English test update (${changes.length} files).`);
  console.log(`Original source backups: ${backup}`);
  console.log('Your saved Canva login, inspection files and dependencies were kept.');
  console.log('Next: npm run build');
  console.log('Then: npm run localise -- english-test');
}
main().catch(error => { console.error(error.message); process.exitCode = 1; });
